package com.cni.report; import com.cni.casefile.CaseRepository; import com.cni.casefile.CaseAccessService; import com.cni.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@RestController @Transactional @RequestMapping("/api/v1/reports") @RequiredArgsConstructor public class ReportController{private final ReportRepository repo;private final CaseRepository cases;private final CaseAccessService access;private final UserRepository users;@GetMapping public List<Map<String,Object>> list(@RequestParam UUID caseId,Authentication a){access.require(caseId,a);return repo.findByInvestigationCase_IdOrderByUpdatedAtDesc(caseId).stream().map(this::view).toList();}@PostMapping public Map<String,Object> create(@RequestBody Req r,Authentication a){var c=access.require(r.caseId(),a);var u=users.findByUsername(a.getName()).orElseThrow();var now=Instant.now();return view(repo.save(InvestigationReport.builder().investigationCase(c).author(u).title(r.title()).content(r.content()).status("DRAFT").createdAt(now).updatedAt(now).build()));}@PutMapping("/{id}")public Map<String,Object> update(@PathVariable UUID id,@RequestBody Req r,Authentication a){var x=repo.findById(id).orElseThrow();access.require(x.getInvestigationCase().getId(),a);if(r.title()!=null)x.setTitle(r.title());if(r.content()!=null)x.setContent(r.content());x.setUpdatedAt(Instant.now());return view(repo.save(x));}private Map<String,Object> view(InvestigationReport r){return Map.of("id",r.getId(),"caseId",r.getInvestigationCase().getId(),"title",r.getTitle(),"content",Objects.toString(r.getContent(),""),"status",r.getStatus(),"author",r.getAuthor().getFullName(),"createdAt",r.getCreatedAt(),"updatedAt",r.getUpdatedAt());}public record Req(UUID caseId,String title,String content){} }
